// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(this)); // exclude deployer/owner to isolate receiver credit
        amount = bound(amount, 1, address(this).balance);

        vm.deal(address(c), amount);
        uint256 before = payable(receiver).balance;

        c.sendTo(receiver, amount);

        assertTrue(payable(receiver).balance == before + amount && address(c).balance == 0);
    }
}
